JS='(function(){\'use strict\';\nconst clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>crypto.randomUUID(),S=v=>String(v??\'\');\nfunction el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}\nfunction button(text,fn){const n=el(\'button\',\'ghost\',text);n.type=\'button\';n.onclick=fn;return n}\nconst exampleFilled=e=>e.positiveKr||e.positiveZh||e.negativeKr||e.negativeZh;\nconst groupFilled=g=>g.title||g.positiveFormula||g.negativeFormula||(g.examples||[]).some(exampleFilled);\nfunction mount(card,x){if(x.kind!==\'polarity\')return;const groups=clone(x.polarityGroups||[]),host=el(\'section\',\'bpol-editor\');const content=card.querySelector(\'[data-tip-field="content"]\')?.closest(\'label\');if(content)content.before(host);else card.append(host);let inputs=[];\nhost.append(el(\'p\',\'bpol-help\',\'一組放一種句型的肯定與否定說法，各組可增加多個韓中例句；最後可填共用補充提醒。\'));const list=el(\'div\',\'bpol-list\');host.append(list);\nfunction collect(){for(const {input,record,key}of inputs){record[key]=input.value;if(window.banaTipTextColors)record[key+\'Highlights\']=banaTipTextColors.collect(input)}return clone(groups)}\nfunction changed(){card.dispatchEvent(new Event(\'input\',{bubbles:true}))}\nfunction structural(fn){collect();fn();render();changed()}\nfunction field(record,key,label){const box=el(\'label\',\'bpol-field\');box.append(el(\'span\',\'\',label));const input=el(\'textarea\',\'bpol-input\');input.rows=1;input.value=S(record[key]);input.dataset.polarityField=key;input.setAttribute(\'aria-label\',label);if(key.endsWith(\'Kr\'))input.lang=\'ko\';if(key.endsWith(\'Zh\'))input.lang=\'zh-Hant\';box.append(input);inputs.push({input,record,key});input.oninput=()=>{record[key]=input.value;changed()};if(window.banaTipTextColors)banaTipTextColors.mount(input,record[key+\'Highlights\']||[]);box.addEventListener(\'click\',changed);return box}\nfunction order(array,i,label,filled){const ops=el(\'div\',\'bpol-ops\');for(const [text,d]of [[\'↑\',-1],[\'↓\',1]]){const b=button(text,()=>structural(()=>{[array[i],array[i+d]]=[array[i+d],array[i]]}));b.disabled=i+d<0||i+d>=array.length;b.setAttribute(\'aria-label\',label+(d<0?\'上移\':\'下移\'));ops.append(b)}ops.append(button(\'刪除\',()=>{collect();if(filled(array[i])&&!confirm(\'刪除這\'+label+\'？\'))return;structural(()=>array.splice(i,1))}));return ops}\nfunction render(){inputs=[];list.replaceChildren();groups.forEach((g,i)=>{g.id=g.id||uid();g.examples=Array.isArray(g.examples)?g.examples:[];const section=el(\'section\',\'bpol-group\');section.dataset.polarityGroup=g.id;const head=el(\'header\',\'bpol-head\');head.append(el(\'b\',\'\',\'對照 \'+(i+1)),order(groups,i,\'組對照\',groupFilled));section.append(head,field(g,\'title\',\'小標題（選填）\'));const formulas=el(\'div\',\'bpol-formulas\');formulas.append(field(g,\'positiveFormula\',\'肯定句型（選填）\'),el(\'span\',\'bpol-arrow\',\'→\'),field(g,\'negativeFormula\',\'否定句型（選填）\'));section.append(formulas);const examples=el(\'div\',\'bpol-examples\');g.examples.forEach((e,j)=>{e.id=e.id||uid();const item=el(\'section\',\'bpol-example-editor\');item.dataset.polarityExample=e.id;const eh=el(\'header\',\'bpol-head\');eh.append(el(\'b\',\'\',\'例句 \'+(j+1)),order(g.examples,j,\'組例句\',exampleFilled));const a=el(\'div\',\'bpol-side bpol-positive\'),b=el(\'div\',\'bpol-side bpol-negative\');a.append(el(\'small\',\'\',\'肯定說法\'),field(e,\'positiveKr\',\'肯定句・韓文\'),field(e,\'positiveZh\',\'肯定句・中文（選填）\'));b.append(el(\'small\',\'\',\'否定說法\'),field(e,\'negativeKr\',\'否定句・韓文\'),field(e,\'negativeZh\',\'否定句・中文（選填）\'));item.append(eh,a,el(\'div\',\'bpol-down\',\'↓\'),b);examples.append(item)});section.append(examples,button(\'＋ 新增例句對照\',()=>structural(()=>g.examples.push({id:uid(),positiveKr:\'\',positiveZh:\'\',negativeKr:\'\',negativeZh:\'\'}))));list.append(section)})}\nhost.append(button(\'＋ 新增一組肯定／否定對照\',()=>structural(()=>groups.push({id:uid(),title:\'\',positiveFormula:\'\',negativeFormula:\'\',examples:[]}))));card.collectPolarityGroups=collect;render()}\nconst esc=s=>S(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c])),rich=(s,h)=>window.banaTipTextColors?banaTipTextColors.html(S(s),h||[]):esc(s);\nconst previous=window.banaGrammarTipsHtml;window.banaGrammarTipsHtml=function(g){const t=document.createElement(\'template\');t.innerHTML=previous(g);const tips=banaGrammarTipModel.clean(banaGrammarTipModel.fromLegacy(g));[...t.content.querySelectorAll(\'.bgt-read-card\')].forEach((card,i)=>{const n=tips[i];if(n?.kind!==\'polarity\')return;card.classList.add(\'bpol-reading\');card.innerHTML=\'<h4>\'+esc(n.title||\'肯定／否定對照\')+\'</h4>\'+(n.polarityGroups||[]).filter(groupFilled).map(group=>\'<section class="bpol-read-group">\'+(group.title?\'<h5>\'+rich(group.title,group.titleHighlights)+\'</h5>\':\'\')+((group.positiveFormula||group.negativeFormula)?\'<div class="bpol-read-formulas">\'+(group.positiveFormula?\'<div>\'+rich(group.positiveFormula,group.positiveFormulaHighlights)+\'</div>\':\'\')+(group.positiveFormula&&group.negativeFormula?\'<span class="bpol-arrow">→</span>\':\'\')+(group.negativeFormula?\'<div>\'+rich(group.negativeFormula,group.negativeFormulaHighlights)+\'</div>\':\'\')+\'</div>\':\'\')+(group.examples||[]).filter(exampleFilled).map(e=>\'<section class="bpol-read-example">\'+(e.positiveKr||e.positiveZh?\'<div class="bpol-positive"><small>肯定</small>\'+(e.positiveKr?\'<p lang="ko">\'+rich(e.positiveKr,e.positiveKrHighlights)+\'</p>\':\'\')+(e.positiveZh?\'<p class="bpol-zh" lang="zh-Hant">\'+rich(e.positiveZh,e.positiveZhHighlights)+\'</p>\':\'\')+\'</div>\':\'\')+((e.positiveKr||e.positiveZh)&&(e.negativeKr||e.negativeZh)?\'<div class="bpol-down">↓</div>\':\'\')+(e.negativeKr||e.negativeZh?\'<div class="bpol-negative"><small>否定</small>\'+(e.negativeKr?\'<p lang="ko">\'+rich(e.negativeKr,e.negativeKrHighlights)+\'</p>\':\'\')+(e.negativeZh?\'<p class="bpol-zh" lang="zh-Hant">\'+rich(e.negativeZh,e.negativeZhHighlights)+\'</p>\':\'\')+\'</div>\':\'\')+\'</section>\').join(\'\')+\'</section>\').join(\'\')+(n.content?\'<div class="bpol-supplement">☆ \'+rich(n.content,n.contentHighlights)+\'</div>\':\'\')});return t.innerHTML};\nwindow.banaPolarityTips={mount};\n})();\n'
CSS='.bpol-editor,.bpol-group,.bpol-side{min-width:0;box-sizing:border-box}.bpol-help{margin:5px 0;color:#829174;line-height:1.5}.bpol-list{display:grid;gap:9px;margin:8px 0}.bpol-group{padding:8px;background:#f3f6ed;border:1px solid #dbe3d1;border-radius:10px}.bpol-head,.bpol-ops{display:flex;gap:4px;align-items:center;justify-content:space-between}.bpol-ops{flex-wrap:wrap;justify-content:flex-end}.bpol-field{display:block;min-width:0;margin:4px 0}.bpol-field>span{display:block;font-size:12px;color:#849575;margin-bottom:3px}.bpol-input{box-sizing:border-box;width:100%;min-height:36px;padding:6px;border:1px solid #d9e1cf;border-radius:7px;background:#fffefb;color:#405f3c;font:inherit;resize:vertical}.bpol-field [contenteditable]{min-height:34px!important}.bpol-field .btc-toolbar{flex-wrap:wrap}.bpol-field .btc-toolbar small{display:none}.bpol-formulas{display:grid;grid-template-columns:minmax(0,1fr) 18px minmax(0,1fr);align-items:start;gap:5px}.bpol-arrow{align-self:center;text-align:center;color:#899e77}.bpol-example-editor{margin:7px 0;padding:7px;background:#fffef9;border-radius:8px;border:1px solid #e1e7d8}.bpol-positive,.bpol-negative{padding:6px 8px;border-radius:7px;min-width:0}.bpol-positive{background:#edf3e6}.bpol-negative{background:#f6f0e5}.bpol-side>small,.bpol-read-example small{display:block;color:#819275;font-size:11px;margin-bottom:2px}.bpol-down{color:#8ca174;line-height:1.1;margin:2px 0 2px 8px}.bpol-reading h4,.bpol-reading h5{margin:0 0 6px}.bpol-read-group+.bpol-read-group{margin-top:12px}.bpol-read-formulas{display:flex;flex-wrap:wrap;align-items:baseline;gap:5px;line-height:1.5}.bpol-read-example{margin-top:6px}.bpol-read-example p{margin:0!important;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5}.bpol-read-example .bpol-zh{color:#95816c;margin-top:2px!important}.bpol-supplement{margin-top:9px;padding-top:7px;border-top:1px dashed #d9e2cc;white-space:pre-wrap;line-height:1.6}.bpol-formulas .brc-swatch{width:19px!important;min-width:19px!important;height:19px!important;min-height:19px!important;padding:0!important}\n'
def apply(path):
 p=Path(path);s=p.read_text(encoding='utf-8')
 if 'bana-polarity-tips-script' in s:return
 changes=[("colloquial:'口語變化',", "colloquial:'口語變化',polarity:'肯定／否定對照',"),
 ("if(card.collectColloquialRows)x.colloquialRows=card.collectColloquialRows();", "if(card.collectColloquialRows)x.colloquialRows=card.collectColloquialRows();if(card.collectPolarityGroups)x.polarityGroups=card.collectPolarityGroups();"),
 ("window.banaColloquialNotes?.mount(card,rows[i]);", "window.banaColloquialNotes?.mount(card,rows[i]);window.banaPolarityTips?.mount(card,rows[i]);"),
 ("||x.noteBlocks?.length||", "||x.noteBlocks?.length||x.polarityGroups?.some(g=>g.title||g.positiveFormula||g.negativeFormula||g.examples?.some(e=>e.positiveKr||e.positiveZh||e.negativeKr||e.negativeZh))||")]
 for old,new in changes:
  assert s.count(old)==1,'Changed integration: '+old
  s=s.replace(old,new,1)
 s=s.replace('</head>','<style id="bana-polarity-tips-style">'+CSS+'</style>\n</head>',1)
 s=s.replace('</body>','<script id="bana-polarity-tips-script">'+JS+'</script>\n</body>',1)
 p.write_bytes(s.encode('utf-8'))
if __name__=='__main__':apply(sys.argv[1] if len(sys.argv)>1 else 'index.html')
